  function seedReference(seed){return seed?.realClub||String(seed?.reference||seed?.name||'').replace(/\\s+(parallel|founder|database)$/i,'')}
  function historicalPredecessor(seed,row){if(!seed||!row||seed.databaseClub)return false;const seedYear=Number(String(seed.founded||seed.systemEntry||seed.leagueEntry||0).slice(0,4))||0,periods=Array.isArray(seed.membershipPeriods)?seed.membershipPeriods:[],stillCurrent=periods.some(period=>period&&period[1]==null);return periods.length>0&&!stillCurrent&&seedYear>0&&Number(row.founded)>=seedYear+8}
  function englishByReference(value){const isSeed=value&&typeof value==='object',row=englishByKey.get(normalise(isSeed?seedReference(value):value))||null;return isSeed&&historicalPredecessor(value,row)?null:row}
  function worldByReference(value){return worldByKey.get(normalise(value))||null}
